/* MCP auth: primary CHAT_API_KEY or managed keys (SHA-256 lookup in gateway_keys). */
const crypto = require("crypto");
const req = $input.first().json;
const headers = req.headers || {};
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '').trim();
const err = (msg) => [{ json: { __error: true, status: 401, body: { jsonrpc: '2.0', id: null, error: { code: -32001, message: msg } } } }];
if (!provided) return err('Missing API key');
if ($env.CHAT_API_KEY && provided === $env.CHAT_API_KEY) return [{ json: { ok: true, key_name: 'primary', rpm: 0 } }];
const sha = crypto.createHash('sha256').update(provided).digest('hex');
const base = 'http://localhost:5678/api/v1';
try {
  const t = await this.helpers.httpRequest({ method: 'GET', url: base + '/data-tables', qs: { limit: 100 }, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 15000 });
  const tb = ((t.data) || []).find((x) => x.name === 'gateway_keys');
  if (!tb) return err('Key store unavailable');
  const rows = await this.helpers.httpRequest({ method: 'GET', url: base + '/data-tables/' + tb.id + '/rows', qs: { limit: 250 }, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 15000 });
  const row = ((rows.data) || []).find((r) => r.key_hash === sha && Number(r.enabled) === 1);
  if (!row) return err('Invalid API key');
  return [{ json: { ok: true, key_name: String(row.name || 'managed'), rpm: Number(row.rate_limit_rpm) || 0 } }];
} catch (e) {
  return err('Auth backend error');
}

/* MCP Server — stateless JSON-RPC (2026-07-28) over the platform's 12 tools. */
/* Compat: legacy initialize shim. Audit: admin_audit (mcp.call). Rate: per-key fixed window. */
const webhookJson = $('Webhook MCP').first().json;
const headers = webhookJson.headers || {};
const authInfo = (() => { try { return $('Auth').first().json || {}; } catch (e) { return {}; } })();
const keyName = String(authInfo.key_name || 'unknown');
const rpm = Number(authInfo.rpm || 0);
const N8N = 'http://localhost:5678/api/v1';
const AUTH_HEAD = ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || '');
const SERVER_INFO = { name: 'agent-platform-mcp', version: '1.0.0' };

/* ---- rate limit (fixed 1-min window per key; staticData; resets on restart) ---- */
const sd = $getWorkflowStaticData('node');
const win = Math.floor(Date.now() / 60000);
sd.rl = sd.rl || {};
const limit = rpm > 0 ? rpm : 60;
const rec = sd.rl[keyName] && sd.rl[keyName].w === win ? sd.rl[keyName] : { w: win, n: 0 };
rec.n += 1;
sd.rl[keyName] = rec;

/* ---- parse ---- */
let rpc = null;
let parseFailed = false;
try {
  const raw = webhookJson.body;
  if (typeof raw === 'string') rpc = JSON.parse(raw);
  else if (raw && typeof raw === 'object' && raw.type === 'Buffer' && Array.isArray(raw.data)) rpc = JSON.parse(Buffer.from(raw.data).toString('utf8'));
  else rpc = raw;
  if (!rpc || typeof rpc !== 'object' || Array.isArray(rpc) || typeof rpc.method !== 'string') throw new Error('bad');
} catch (e) { parseFailed = true; }
const rid = !parseFailed && rpc.id !== undefined ? rpc.id : null;
const method = parseFailed ? '' : String(rpc.method);
const clientInfo = (() => { try { const m = rpc.params && rpc.params._meta; const ci = m && m['io.modelcontextprotocol/clientInfo']; return ci ? String(ci.name || '') + '/' + String(ci.version || '') : ''; } catch (e) { return ''; } })();
const proto = String(headers['mcp-protocol-version'] || '');
const fail = (code, msg, httpCode) => [{ json: { __code: httpCode || 200, rpcResponse: { jsonrpc: '2.0', id: rid, error: { code, message: msg } } } }];
const done = (result, httpCode) => [{ json: { __code: httpCode || 200, rpcResponse: { jsonrpc: '2.0', id: rid, result } } }];

if (rec.n > limit) return fail(-32029, 'Rate limit exceeded (' + limit + '/min). Retry within a minute.', 429);
if (parseFailed) return fail(-32700, 'Parse error: invalid JSON');
if (!method) return fail(-32600, 'Invalid Request: missing method');
if (rpc.id === undefined) return [{ json: { __code: 202, rpcResponse: {} } }]; /* notification */

/* ---- tool catalog (mirrors chat-gateway; single source of truth for dispatch) ---- */
const TOOLS = [
  { name: 'web_search', description: 'Search the public web for current information, facts, news or documentation. Returns ranked results with title, url and snippet.', inputSchema: { type: 'object', properties: { query: { type: 'string', description: 'The search query' } }, required: ['query'] }, annotations: { readOnlyHint: true, openWorldHint: true } },
  { name: 'kb_search', description: 'Search the private knowledge base (ingested internal documents, notes and references). Returns passages with title, excerpt and relevance.', inputSchema: { type: 'object', properties: { query: { type: 'string', description: 'The search query' }, top_k: { type: 'integer', description: 'How many passages (1-10, default 6)' } }, required: ['query'] }, annotations: { readOnlyHint: true } },
  { name: 'platform_status', description: 'Get live status of the personal AI platform: chat traffic, error rate, latency, alerts and knowledge base usage.', inputSchema: { type: 'object', properties: {} }, annotations: { readOnlyHint: true } },
  { name: 'run_brief', description: 'Generate the daily brief right now (fetches fresh sources and saves it). Takes about 30-60 seconds. Returns the brief.', inputSchema: { type: 'object', properties: {} }, annotations: { readOnlyHint: false, openWorldHint: true } },
  { name: 'list_alerts', description: 'List recent platform alerts (errors, threshold breaches) with severity and time.', inputSchema: { type: 'object', properties: { limit: { type: 'integer', description: 'How many alerts (1-20, default 8)' } } }, annotations: { readOnlyHint: true } },
  { name: 'kb_save', description: 'Save a note, passage or excerpt into the private knowledge base so it can be searched later. Args: title (short label), text (full content).', inputSchema: { type: 'object', properties: { title: { type: 'string', description: 'Short descriptive title' }, text: { type: 'string', description: 'The full text content to store' } }, required: ['title', 'text'] }, annotations: { readOnlyHint: false } },
  { name: 'create_reminder', description: 'Create a reminder that is pushed at the due time. Provide text plus either due_at (ISO 8601 with timezone) or delay_minutes. Pass owner (a name from people_list) to remind someone else. Current user timezone: Asia/Shanghai (UTC+8).', inputSchema: { type: 'object', properties: { text: { type: 'string', description: 'What to remind about' }, due_at: { type: 'string', description: 'ISO 8601 time with timezone' }, delay_minutes: { type: 'integer', description: 'Alternative: remind after N minutes' }, owner: { type: 'string', description: 'Optional assignee name from the people directory' } }, required: ['text'] }, annotations: { readOnlyHint: false } },
  { name: 'list_reminders', description: 'List upcoming (pending) and recent reminders with their status.', inputSchema: { type: 'object', properties: {} }, annotations: { readOnlyHint: true } },
  { name: 'cancel_reminder', description: 'Cancel a pending reminder by id.', inputSchema: { type: 'object', properties: { id: { type: 'integer', description: 'Reminder id (from list_reminders)' } }, required: ['id'] }, annotations: { readOnlyHint: false, destructiveHint: true } },
  { name: 'todo_add', description: 'Save an open-loop item (todo). Optional due_date as YYYY-MM-DD, and optional owner (a name from people_list) to assign it to someone else.', inputSchema: { type: 'object', properties: { text: { type: 'string', description: 'What to remember to do' }, due_date: { type: 'string', description: 'Optional due date, YYYY-MM-DD' }, owner: { type: 'string', description: 'Optional assignee name from the people directory' } }, required: ['text'] }, annotations: { readOnlyHint: false } },
  { name: 'todo_list', description: 'List open todos with overdue and due-today flags, plus recently completed ones. Pass owner to filter by assignee (use "mine" for the user own unassigned todos).', inputSchema: { type: 'object', properties: { owner: { type: 'string', description: 'Optional person name, or "mine"' } } }, annotations: { readOnlyHint: true } },
  { name: 'todo_done', description: 'Complete (check off) a todo by id.', inputSchema: { type: 'object', properties: { id: { type: 'integer', description: 'Todo id (from todo_list)' } }, required: ['id'] }, annotations: { readOnlyHint: false } },
  { name: 'people_list', description: 'List the people directory — the assignees available for todos and reminders. Shows each person name, role, and whether they have a direct delivery channel (without one, delivery falls back to the owner).', inputSchema: { type: 'object', properties: {} }, annotations: { readOnlyHint: true } },
  { name: 'delegation_view', description: 'See what has been handed out and where it is stuck: totals, a per-person breakdown (open, overdue, awaiting acknowledgement, average acknowledgement time, never acknowledged) and the longest-waiting item. This is the "what am I waiting on other people for" view.', inputSchema: { type: 'object', properties: {} }, annotations: { readOnlyHint: true } },
  { name: 'doc_create', description: 'Create a deliverable document. kind=minutes turns raw meeting notes into a structured minute with an action table (owners and due dates extracted); kind=weekly or kind=brief exports the latest weekly review / daily brief; kind=custom stores the given text as-is. Returns the document id and a login-free shareable link.', inputSchema: { type: 'object', properties: { kind: { type: 'string', description: 'minutes | weekly | brief | custom' }, title: { type: 'string', description: 'Optional title' }, text: { type: 'string', description: 'Raw content (required for minutes and custom)' } }, required: ['kind'] }, annotations: { readOnlyHint: false } },
  { name: 'doc_list', description: 'List recently created documents with id, kind, title and summary.', inputSchema: { type: 'object', properties: { limit: { type: 'integer', description: 'How many (1-30, default 10)' } } }, annotations: { readOnlyHint: true } },
  { name: 'doc_get', description: 'Read one document: returns its plain text plus a login-free link valid for 7 days, so it can be forwarded to someone else.', inputSchema: { type: 'object', properties: { id: { type: 'integer', description: 'Document id (from doc_list or doc_create)' } }, required: ['id'] }, annotations: { readOnlyHint: true } },
];
const TOOL_MAP = {};
TOOLS.forEach((t) => { TOOL_MAP[t.name] = t; });

const iso8 = (t) => { const ms = Date.parse(t); return isNaN(ms) ? String(t || '') : new Date(ms + 8 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ') + ' +08'; };
/* Surface the upstream error message instead of a bare status code: a 400 saying
   "unknown person: 张三" is actionable by the model, "Request failed with status code 400" is not.
   n8n throws a flattened error with no response body attached, so we ask for the full
   response and inspect the status ourselves. */
const unwrap = (r, sc) => {
  let data = r && (r.body !== undefined ? r.body : r);
  if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { data = null; } }
  const code = Number(sc || (r && (r.statusCode || r.status)) || 200);
  if (code >= 400) {
    const msg = (data && data.error && (data.error.message || data.error.code)) || ('upstream http ' + code);
    return { ok: false, error: String(msg).slice(0, 300) };
  }
  return data || { ok: false, error: 'empty upstream response' };
};
const apiGet = async (url, timeout) => {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: AUTH_HEAD }, timeout: timeout || 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return unwrap(r);
  } catch (e) { return { ok: false, error: String((e && e.message) || e).slice(0, 300) }; }
};
const apiPost = async (url, body, timeout) => {
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url, headers: { Authorization: AUTH_HEAD, 'Content-Type': 'application/json' }, body, timeout: timeout || 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return unwrap(r);
  } catch (e) { return { ok: false, error: String((e && e.message) || e).slice(0, 300) }; }
};

async function audit(name, args, okFlag, ms) {
  try {
    if (!sd.auditId) {
      const t = await this.helpers.httpRequest({ method: 'GET', url: N8N + '/data-tables', qs: { limit: 100 }, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 15000 });
      const tb = ((t.data) || []).find((x) => x.name === 'admin_audit');
      if (tb) sd.auditId = tb.id;
    }
    if (!sd.auditId) return;
    const detail = JSON.stringify({ args: JSON.stringify(args || {}).slice(0, 300), ok: okFlag, ms, client: clientInfo, proto }).slice(0, 900);
    await this.helpers.httpRequest({ method: 'POST', url: N8N + '/data-tables/' + sd.auditId + '/rows', headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, body: { data: [{ action: 'mcp.call', target: name, detail }] }, timeout: 15000 });
  } catch (e) {}
}

async function runTool(name, args) {
  try {
    if (name === 'web_search') {
      const q = String((args && args.query) || '').trim();
      if (!q) return { text: 'web_search requires a query', isError: true };
      const res = await this.helpers.httpRequest({ method: 'GET', url: 'http://searxng:8080/search', qs: { q, format: 'json' }, headers: { Accept: 'application/json' }, timeout: 20000 });
      const rs = (res.results || []).slice(0, 5);
      return { text: rs.length ? rs.map((r, i) => (i + 1) + '. ' + r.title + '\n   ' + r.url + '\n   ' + String(r.content || '').slice(0, 220)).join('\n\n') : 'No web results for: ' + q };
    }
    if (name === 'kb_search') {
      const q = String((args && args.query) || '').trim();
      if (!q) return { text: 'kb_search requires a query', isError: true };
      const emb = await this.helpers.httpRequest({ method: 'POST', url: 'https://dashscope.aliyuncs.com/api/v1/services/embeddings/text-embedding/text-embedding', headers: { Authorization: ['Bea', 'rer '].join('') + ($env.DASHSCOPE_API_KEY || ''), 'Content-Type': 'application/json' }, body: { model: 'qwen3.7-text-embedding', input: { texts: [q] }, parameters: { dimension: 1024, text_type: 'query', output_type: 'dense' } }, timeout: 30000 });
      const vec = emb.output.embeddings[0].embedding;
      const { Client } = require('pg');
      const pg = new Client({ host: $env.DB_POSTGRESDB_HOST || 'postgres', port: Number($env.DB_POSTGRESDB_PORT || 5432), database: $env.DB_POSTGRESDB_DATABASE || 'n8n', user: $env.DB_POSTGRESDB_USER || 'n8n', password: $env.DB_POSTGRESDB_PASSWORD });
      await pg.connect();
      try {
        const k = Math.min(Math.max(Number(args && args.top_k) || 6, 1), 10);
        const r = await pg.query('SELECT c.content, c.seq, d.title, 1 - (c.embedding <=> $1::vector) AS score FROM kb_chunks c JOIN kb_documents d ON d.doc_id = c.doc_id WHERE d.status = ' + String.fromCharCode(39) + 'active' + String.fromCharCode(39) + ' ORDER BY c.embedding <=> $1::vector LIMIT $2', ['[' + vec.join(',') + ']', k]);
        const rows = r.rows.filter((x) => Number(x.score) > 0.2);
        return { text: rows.length ? rows.map((x, i) => (i + 1) + '. [' + x.title + ' #' + x.seq + ' · score ' + (Math.round(Number(x.score) * 1000) / 1000) + ']\n   ' + String(x.content).slice(0, 500)).join('\n\n') : 'No relevant passages found in the knowledge base.' };
      } finally { await pg.end().catch(() => {}); }
    }
    if (name === 'platform_status') {
      const r = await apiGet('http://localhost:5678/webhook/admin/overview', 20000);
      const c = r.chat_24h || {};
      const a = (r.alerts && r.alerts.recent) || [];
      const kb = r.kb || {};
      const lines = [];
      lines.push('Platform status at ' + String(r.generated_at || '') + ':');
      lines.push('- Chat 24h: ' + (c.total || 0) + ' calls (ok ' + (c.success || 0) + ' / err ' + (c.error || 0) + '), error rate ' + (Math.round((c.error_rate || 0) * 1000) / 10) + '%, avg latency ' + Math.round((c.avg_latency_ms || 0) / 100) / 10 + 's, cost $' + (Math.round((c.cost_usd || 0) * 1000) / 1000) + ', sessions ' + (c.unique_sessions || 0));
      lines.push('- Alerts: ' + ((r.alerts && r.alerts.recent_count) || 0) + ' recent' + (a[0] ? ' (latest: ' + String(a[0].message).slice(0, 80) + ' at ' + iso8(a[0].created_at) + ')' : ''));
      lines.push('- KB: ' + (kb.documents || 0) + ' docs / ' + (kb.chunks || 0) + ' chunks, embed usage ' + (kb.embed_pct || 0) + '%');
      return { text: lines.join('\n') };
    }
    if (name === 'run_brief') {
      const r = await apiPost('http://localhost:5678/webhook/admin/briefs/run', {}, 90000);
      const content = String((r && r.content_md) || '');
      return { text: 'Brief 「' + String((r && r.title) || '') + '」 generated and saved.\n\n' + content.slice(0, 2400) };
    }
    if (name === 'list_alerts') {
      const r = await apiGet('http://localhost:5678/webhook/admin/alerts', 20000);
      const list = (r.alerts || []).slice(0, Number((args && args.limit) || 8));
      return { text: list.length ? list.map((x, i) => (i + 1) + '. [' + iso8(x.created_at) + '] ' + x.kind + ' — ' + String(x.message).slice(0, 140)).join('\n') : 'No recent alerts.' };
    }
    if (name === 'kb_save') {
      const title = String((args && args.title) || '').trim().slice(0, 120) || 'MCP note';
      const text = String((args && args.text) || '').trim().slice(0, 8000);
      if (!text) return { text: 'kb_save requires text', isError: true };
      const r = await apiPost('http://localhost:5678/webhook/admin/kb/ingest', { mode: 'ingest', title, text, source_type: 'mcp' }, 120000);
      return { text: 'Saved to knowledge base: "' + title + '" (doc_id ' + String((r && r.doc_id) || '?') + ', chunks ' + String((r && r.chunks) || '?') + ')' };
    }
    if (name === 'create_reminder') {
      const r = await apiPost('http://localhost:5678/webhook/admin/reminders/create', { text: String((args && args.text) || '').slice(0, 500), due_at: (args && args.due_at) || undefined, delay_minutes: (args && args.delay_minutes) || undefined, owner: (args && args.owner) || undefined, via: 'mcp' }, 20000);
      if (r && r.ok === false) return { text: 'Reminder not created: ' + String(r.error || 'unknown'), isError: true };
      return { text: 'Reminder #' + String((r && r.id) || '?') + ' created: ' + String((args && args.text) || '') + (r && r.due_local ? ' (due ' + r.due_local + ')' : '') + '. It will be pushed at the due time.' };
    }
    if (name === 'list_reminders') {
      const r = await apiGet('http://localhost:5678/webhook/admin/reminders', 20000);
      const p = r.pending || [];
      const rec = r.recent || [];
      const lines = ['Pending: ' + (r.pending_count || p.length) + (p.length ? '\n' + p.map((x) => '• #' + x.id + ' ' + x.text + (x.due_local ? ' (' + x.due_local + ')' : '')).join('\n') : '')];
      if (rec.length) lines.push('Recent:\n' + rec.slice(0, 5).map((x) => '• #' + x.id + ' [' + x.status + '] ' + x.text).join('\n'));
      return { text: lines.join('\n') };
    }
    if (name === 'cancel_reminder') {
      const id = Number((args && args.id) || 0);
      if (!id) return { text: 'cancel_reminder requires id', isError: true };
      const r = await apiPost('http://localhost:5678/webhook/admin/reminders/cancel', { id }, 15000);
      if (r && r.ok === false) return { text: 'Cancel failed: ' + String(r.error || 'unknown'), isError: true };
      return { text: 'Reminder #' + id + ' cancelled.' };
    }
    if (name === 'todo_add') {
      const r = await apiPost('http://localhost:5678/webhook/admin/todos/add', { text: String((args && args.text) || '').slice(0, 300), due_date: (args && args.due_date) || undefined, owner: (args && args.owner) || undefined, via: 'mcp' }, 15000);
      if (r && r.ok === false) return { text: 'Todo not added: ' + String(r.error || 'unknown'), isError: true };
      const t = (r && (r.todo || r.item)) || {};
      return { text: 'Todo #' + String(t.id || (r && r.id) || '?') + ' added: ' + String((args && args.text) || '') + ((args && args.due_date) ? ' (due ' + args.due_date + ')' : '') + '.' };
    }
    if (name === 'todo_list') {
      const tOwner = String((args && args.owner) || '').trim().replace(/^@/, '');
      const r = await apiGet('http://localhost:5678/webhook/admin/todos' + (tOwner ? '?owner=' + encodeURIComponent(tOwner) : ''), 15000);
      const open = r.open || [];
      const lines = ['Open todos: ' + (r.open_count || open.length) + ' (overdue ' + (r.overdue_count || 0) + ', due today ' + (r.due_today_count || 0) + ')'];
      open.forEach((x) => lines.push('• #' + x.id + ' ' + x.text + (x.due_date ? ' (due ' + x.due_date + (x.overdue ? ' · OVERDUE' : '') + ')' : '')));
      const done = r.done_recent || [];
      if (done.length) lines.push('Recently done: ' + done.slice(0, 5).map((x) => '#' + x.id + ' ' + x.text).join(' · '));
      return { text: lines.join('\n') };
    }
    if (name === 'todo_done') {
      const id = Number((args && args.id) || 0);
      if (!id) return { text: 'todo_done requires id', isError: true };
      const r = await apiPost('http://localhost:5678/webhook/admin/todos/complete', { id }, 15000);
      if (r && r.ok === false) return { text: 'Complete failed: ' + String(r.error || 'unknown'), isError: true };
      return { text: 'Todo #' + id + ' completed.' };
    }
    if (name === 'people_list') {
      const r = await apiGet('http://localhost:5678/webhook/admin/people', 15000);
      const ps = (r && r.people) || [];
      if (!ps.length) return { text: 'The people directory is empty. Add people on the console People page first.' };
      const lines = ['People: ' + ps.length];
      ps.forEach((p) => {
        let hasCh = false;
        try { const ch = JSON.parse(p.channels || '{}'); hasCh = Object.keys(ch).some((k) => ch[k]); } catch (e) { hasCh = false; }
        lines.push('• @' + p.name + ' — ' + (p.display_name || p.name) + ' [' + (p.role || 'member') + (p.active ? '' : ', INACTIVE') + ']' + (hasCh ? '' : ' · no channel (delivery falls back to owner)'));
      });
      return { text: lines.join('\n') };
    }
    if (name === 'delegation_view') {
      const r = await apiGet('http://localhost:5678/webhook/admin/delegation', 30000);
      const t = (r && r.totals) || {};
      const lines = ['Delegated: open ' + (t.assigned_open || 0) + ' · overdue ' + (t.overdue || 0) + ' · awaiting ack ' + (t.awaiting_ack || 0) + (t.escalated ? ' · escalated ' + t.escalated : '') + ' · done in 7d ' + (t.done_7d || 0) + (t.channel_less ? ' · ' + t.channel_less + ' without a channel' : '')];
      ((r && r.people) || []).filter((p) => p.open > 0).forEach((p) => lines.push('• ' + p.display_name + ': open ' + p.open + (p.overdue ? ' (overdue ' + p.overdue + (p.oldest_overdue_days ? ', oldest ' + p.oldest_overdue_days + 'd' : '') + ')' : '') + ' · awaiting ack ' + p.awaiting_ack + ' · done 7d ' + p.done_7d + (p.has_channel ? '' : ' · NO CHANNEL')));
      const ow = r && r.oldest_waiting;
      if (ow) lines.push('Longest waiting: #' + ow.id + ' ' + String(ow.text).slice(0, 40) + ' (' + ow.owner + ', ' + ow.days_late + 'd late)');
      return { text: lines.join('\n') };
    }
    if (name === 'doc_create') {
      const kind = String((args && args.kind) || '').toLowerCase();
      if (['minutes', 'weekly', 'brief', 'custom'].indexOf(kind) < 0) return { text: 'doc_create requires kind = minutes | weekly | brief | custom', isError: true };
      const payload = { action: 'create', kind };
      if (args && args.title) payload.title = String(args.title).slice(0, 120);
      if (args && args.text) payload.text = String(args.text).slice(0, 6000);
      const r = await apiPost('http://localhost:5678/webhook/admin/docforge', payload, 120000);
      if (!r || r.ok === false) return { text: 'Document not created: ' + String((r && r.error) || 'unknown'), isError: true };
      let url = '';
      try { const s = await apiPost('http://localhost:5678/webhook/admin/docforge', { action: 'sign', id: r.id }, 30000); url = (s && s.url) || ''; } catch (e) {}
      return { text: 'Document #' + r.id + ' (' + kind + ') created: ' + r.title + (r.actions ? ' — ' + r.actions + ' action item(s) extracted' : '') + (url ? '\nShareable link (7 days, no login): ' + url : '') };
    }
    if (name === 'doc_list') {
      const lim = Number((args && args.limit) || 10);
      const r = await apiPost('http://localhost:5678/webhook/admin/docforge', { action: 'list', limit: (Number.isFinite(lim) && lim > 0) ? Math.min(lim, 30) : 10 }, 30000);
      const ds = (r && r.docs) || [];
      if (!ds.length) return { text: 'No documents yet. Use doc_create to make one.' };
      const lines = ['Documents: ' + ds.length];
      ds.forEach((d) => lines.push('• #' + d.id + ' [' + d.kind + '] ' + String(d.title).slice(0, 50) + (d.summary ? ' — ' + String(d.summary).slice(0, 60) : '')));
      return { text: lines.join('\n') };
    }
    if (name === 'doc_get') {
      const id = Number((args && args.id) || 0);
      if (!id) return { text: 'doc_get requires id', isError: true };
      const r = await apiPost('http://localhost:5678/webhook/admin/docforge', { action: 'get', id }, 30000);
      if (!r || r.ok === false || !r.html) return { text: 'Document #' + id + ' not found', isError: true };
      const plain = String(r.html)
        .replace(/<style[\s\S]*?<\/style>/gi, '')
        .replace(/<head[\s\S]*?<\/head>/gi, '')
        .replace(/<\/(p|div|h1|h2|h3|tr|li)>/gi, '\n')
        .replace(/<\/t[dh]>/gi, ' | ')
        .replace(/<[^>]+>/g, '')
        .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
        .split('\n').map((x) => x.trim()).filter(Boolean).join('\n');
      let url = '';
      try { const s = await apiPost('http://localhost:5678/webhook/admin/docforge', { action: 'sign', id }, 30000); url = (s && s.url) || ''; } catch (e) {}
      return { text: String(r.title) + '\n\n' + plain.slice(0, 3500) + (url ? '\n\nShareable link (7 days, no login): ' + url : '') };
    }
    return { text: 'Unknown tool: ' + name, isError: true };
  } catch (e) {
    return { text: 'Tool failed: ' + String((e && e.message) || e).slice(0, 300), isError: true };
  }
}

/* ---- dispatch ---- */
if (method === 'initialize') {
  const r = { protocolVersion: String((rpc.params && rpc.params.protocolVersion) || '2025-06-18'), capabilities: { tools: { listChanged: false } }, serverInfo: SERVER_INFO, instructions: 'Agent Platform tools: todos, reminders, knowledge base, briefs, web search, platform status.' };
  return done(r);
}
if (method === 'server/discover') return done({ capabilities: { tools: {} }, serverInfo: SERVER_INFO });
if (method === 'ping') return done({});
if (method === 'tools/list') return done({ tools: TOOLS.map((t) => ({ name: t.name, description: t.description, inputSchema: t.inputSchema, annotations: t.annotations })) });
if (method === 'tools/call') {
  const name = String((rpc.params && rpc.params.name) || '');
  const args = (rpc.params && rpc.params.arguments) || {};
  if (!TOOL_MAP[name]) return fail(-32602, 'Unknown tool: ' + name);
  const t0 = Date.now();
  const out = await runTool(name, args);
  await audit(name, args, !out.isError, Date.now() - t0);
  return done({ content: [{ type: 'text', text: String(out.text).slice(0, 6000) }], isError: !!out.isError });
}
return fail(-32601, 'Method not found: ' + method);
